<template>
  <div class="container">
    <h1>Compilador Comida</h1>
    <textarea v-model="codigo" placeholder="Digite seu código aqui..."></textarea>
    <button @click="cozinhar">Cozinhar</button>
    <p v-if="mensagem" :class="{'sucesso': sucesso, 'erro': !sucesso}">{{ mensagem }}</p>
  </div>
</template>

<script>
import axios from 'axios';

export default {
  data() {
    return {
      codigo: "",
      mensagem: "",
      sucesso: false,
    };
  },
  methods: {
    async cozinhar() {
      try {
        const response = await axios.post("http://localhost:8080/api/compilar", { codigo: this.codigo });
        this.mensagem = response.data.mensagem;
        this.sucesso = response.data.sucesso;
      } catch (error) {
        this.mensagem = "Erro ao compilar o código.";
        this.sucesso = false;
      }
    },
  },
};
</script>

<style scoped>
.container {
  max-width: 600px;
  margin: auto;
  text-align: center;
}
textarea {
  width: 100%;
  height: 200px;
  margin: 10px 0;
  font-family: monospace;
}
button {
  padding: 10px 20px;
  background-color: #28a745;
  color: white;
  border: none;
  cursor: pointer;
}
button:hover {
  background-color: #218838;
}
.sucesso {
  color: green;
}
.erro {
  color: red;
}
</style>
